nested:
struct S{x:i16,y:i16[2]}
struct H{head:i8,items:S[2]}
fn main(){var h:H=H{head:1,items:[S{x:2,y:[3,-4]},S{x:-5,y:[6,7]}]};var n:H=-h;assert(n.head == -1);assert(n.items[0].x == -2);assert(n.items[0].y[1]==4);assert(n.items[1].x==5);assert(n.items[1].y[0] == -6);assert(h.items[1].y[0]==6);print("nested");}

data:
struct S{x:i8,y:i64,z:i16[2]}
recursive fn neg(p:S&)->S{return -p;}
fn main(){var rows:S[]=[S{x:1,y:2,z:[3,-4]},S{x:-5,y:6,z:[7,8]}];var s:S=neg(rows[1]);assert(s.x==5);assert(s.y == -6);assert(s.z[0] == -7);var out:S[]=[-rows[0],-s];assert(out[0].x == -1);assert(out[0].z[1]==4);assert(out[1].x == -5);assert(out[1].z[1]==8);assert(rows[0].x==1);print("data");}

projected:
struct S{n:i64,items:i64[2]}
recursive fn make()->S{return S{n:7,items:[8,-9]};}
fn main(){assert((-make()).n == -7);assert((-make()).items[1]==9);print("projected");}

argument_result:
struct S{x:i64,y:i64}
recursive fn sum(s:S)->i64{return s.x+s.y;}
recursive fn neg(s:S&)->S{return -s;}
fn main(){var s:S=S{x:7,y:8};assert(sum(-s) == -15);var n:S=neg(s);assert(n.x == -7);assert(s.x==7);print("argument_result");}

inline_callback:
struct S{n:i64}
inline fn make(n:i64)->S{if n==0{return S{n:3};}return S{n:n};}
fn apply<F>(n:i64)->S{-F(n)}
fn main(){var a:S=-make(0);assert(a.n == -3);var b:S=apply(7){n=>S{n:n}};assert(b.n == -7);print("inline_callback");}

recursion:
struct S{x:i64,y:i64}
recursive fn make(n:i64)->S{if n==0{return S{x:1,y:2};}return -make(n-1);}
fn main(){var a:S=make(4);var b:S=make(3);assert(a.x==1);assert(b.y == -2);print("recursion");}

defer:
struct S{n:i64}
var calls:i64=0;recursive fn make()->S{var s:S=S{n:7};defer{s.n=99;calls++;}return s;}
fn main(){var s:S=-make();assert(s.n == -7);assert(calls==1);print("defer");}

global:
struct S{n:i64}
recursive fn make()->S{return S{n:7};}
var value:S=-make();
fn main(){assert(value.n == -7);print("global");}

double:
struct S{n:i64}
recursive fn make()->S{return S{n:7};}
fn main(){var s:S=-(-make());assert(s.n==7);print("double");}

early:
struct S{n:i64}
recursive fn run(early:bool)->S{var s:S=-({if early{return S{n:7};}S{n:7}});return s;}
fn main(){var a:S=run(true);var b:S=run(false);assert(a.n==7);assert(b.n == -7);print("early");}
